from pypdf import PdfReader
from pathlib import Path
import re

files = {
'dband':'assets/uploads/4f5e4269_2024-SACs&taloring D band-high-valent metal-oxo species.pdf',
'review':'assets/uploads/34efc7a9_High-valent metal-oxo species in catalytic oxidations for environmental.pdf'
}
keywords = {
'dband':['d-band', 'polymerization', 'phenoxyl', 'peroxymonosulfate', 'binding strength', 'single-atom', 'Co', 'selective', 'oxo'],
'review':['selective oxidation','anti-interference','pH','probe','isotope','18O','Co(IV)','OAT','PCET','limitations']
}
for name, f in files.items():
    print('\n###', name, f)
    reader = PdfReader(f)
    texts=[]
    for i,p in enumerate(reader.pages):
        try:
            t = p.extract_text() or ''
        except Exception:
            t=''
        texts.append(t)
    for kw in keywords[name]:
        print('\nKEYWORD', kw)
        found=False
        for i,t in enumerate(texts):
            if kw.lower() in t.lower():
                found=True
                idx=t.lower().find(kw.lower())
                snip=t[max(0,idx-250):idx+600]
                snip=snip.replace('\n',' ')
                print('page', i+1, ':', snip[:850])
                break
        if not found:
            print('not found')
